/**
 * KANO LIFE — narrow geometry-backed validation for catalogued keke GLBs.
 * This helper never loads assets and cannot promote an arbitrary external path.
 */
export function isCataloguedKekeModelPath(value) {
  if (typeof value !== 'string') return false;
  const path = value.replace(/\\/g, '/').split(/[?#]/, 1)[0];
  if (path.includes('..')) return false;
  return /(?:^|\/)vehicles\/keke\/keke-[1-8]\.glb$/i.test(path);
}

const ALLOWED_CATALOG_GEOMETRY_FAILURES = new Set([
  'missing-vehicle-structure-evidence',
  // The existing validator reports this when its autogenerated seated driver
  // is named, but the vehicle GLB itself uses generic mesh names.
  'character-only-model-no-vehicle-structure',
  // The strict renderer can report out-of-range world bounds when the GLB's
  // root transform differs from the normalized mesh-local geometry. This is
  // eligible only when the remeasured, root-relative geometry passes every
  // dimension and chassis/wheel check below.
  'implausible-keke-bounds',
]);

/**
 * A catalogued keke may pass the name-evidence failure only when its measured
 * geometry supplies independent wheel or chassis/body evidence. Geometry and
 * dimensions remain mandatory; bad bounds, hidden meshes and unrelated failure
 * reasons are not overridden.
 */
export function decideCataloguedKekeValidation(input = {}) {
  const path = input.path;
  const reason = input.originalReason;
  const width = Number(input.width);
  const height = Number(input.height);
  const depth = Number(input.depth);
  const meshCount = Number(input.meshCount);
  const wheelLikeCount = Number(input.wheelLikeCount);
  const broadBodyCount = Number(input.broadBodyCount);

  if (!isCataloguedKekeModelPath(path)) {
    return { accept: false, reason: 'untrusted-model-path' };
  }
  if (!ALLOWED_CATALOG_GEOMETRY_FAILURES.has(reason)) {
    return { accept: false, reason: 'not-an-eligible-geometry-recheck-failure' };
  }
  if (![width, height, depth, meshCount, wheelLikeCount, broadBodyCount]
    .every(Number.isFinite)) {
    return { accept: false, reason: 'non-finite-geometry-evidence' };
  }

  // ModelManager normalises every catalogued keke to 1.85 m high. The wider
  // tolerances allow authentic body proportions without admitting tiny props,
  // character-only GLBs of unrealistic scale, or collapsed geometry.
  if (
    width < 0.62 || width > 2.75 ||
    height < 0.72 || height > 3.35 ||
    depth < 0.78 || depth > 3.8 ||
    width * depth < 0.48 || width * depth > 10.45 ||
    meshCount < 3 || meshCount > 2500
  ) {
    return { accept: false, reason: 'implausible-keke-geometry' };
  }

  const wheelEvidence = wheelLikeCount >= 2;
  // At least one substantial low body mesh and several separate rendered
  // components are required when the source does not expose wheel names.
  // Do not reject these generic-named body meshes just because the separate
  // generated driver is also counted as character geometry by the renderer.
  const bodyAndPartsEvidence = broadBodyCount >= 1 && meshCount >= 8;
  if (!wheelEvidence && !bodyAndPartsEvidence) {
    return { accept: false, reason: 'insufficient-geometric-vehicle-evidence' };
  }

  return {
    accept: true,
    reason: 'catalogued-keke-path-and-geometric-vehicle-evidence',
    originalReason: reason,
    path: path.replace(/\\/g, '/'),
    bounds: { width, height, depth },
    meshCount,
    wheelLikeCount,
    broadBodyCount,
  };
}
